const update = $input.first().json;
const allowedChatId = '5988211094';
const allowedUserId = '5988211094';

// 1. Button click (callback_query)
if (update.callback_query) {
  const cb = update.callback_query;
  if (String(cb.from?.id) !== allowedUserId || String(cb.message?.chat?.id) !== allowedChatId) return [];

  const data = String(cb.data || '');
  const msgText = String(cb.message?.text || '');

  if (data === 'pub:cancel') {
    return [{
      json: {
        action: 'cancel',
        query_id: cb.id,
        chat_id: String(cb.message.chat.id),
        message_id: cb.message.message_id,
        alert_text: 'Đã hủy yêu cầu.'
      }
    }];
  }

  const match = msgText.match(/https?:\/\/(?:www\.|m\.|vm\.|vt\.)?tiktok\.com\/[^\s\n]+/i);
  const url = match ? match[0].replace(/[,.!?]+$/, '') : '';

  if (!url) {
    return [{
      json: {
        action: 'cancel',
        query_id: cb.id,
        chat_id: String(cb.message.chat.id),
        message_id: cb.message.message_id,
        alert_text: 'Không tìm thấy link video trong tin nhắn.'
      }
    }];
  }

  let privacy = 'public';
  let shorts_mode = 'short';
  let target_platform = 'youtube';
  let label = '🔴 YouTube Shorts';

  if (data === 'pub:yt_short' || data === 'pub:short') {
    privacy = 'public';
    shorts_mode = 'short';
    target_platform = 'youtube';
    label = '🔴 YouTube Shorts';
  } else if (data === 'pub:yt_video' || data === 'pub:video') {
    privacy = 'public';
    shorts_mode = 'video';
    target_platform = 'youtube';
    label = '🔴 YouTube Video';
  } else if (data === 'pub:fb_reel') {
    privacy = 'public';
    shorts_mode = 'short';
    target_platform = 'facebook';
    label = '🔵 Facebook Reels';
  } else if (data === 'pub:fb_video') {
    privacy = 'public';
    shorts_mode = 'video';
    target_platform = 'facebook';
    label = '🔵 Facebook Video';
  } else if (data === 'pub:both') {
    privacy = 'public';
    shorts_mode = 'short';
    target_platform = 'both';
    label = '🚀 YouTube Shorts & FB Reels';
  } else if (data === 'pub:yt_private' || data === 'pub:private') {
    privacy = 'private';
    shorts_mode = 'short';
    target_platform = 'youtube';
    label = '🔒 YouTube Riêng tư';
  }

  const reqKey = 'tg_' + String(cb.message.chat.id).replace('-', 'n') +
                 '_' + String(cb.message.message_id) + '_' + data.replace(':', '_') + '_v6';

  const bar = '🟩⬜⬜⬜⬜⬜⬜⬜⬜⬜';
  let step3 = '⚪ Tối ưu định dạng & thẻ video\n';
  let step4 = '⚪ Đăng lên YouTube Studio';
  if (target_platform === 'facebook') {
    step3 = '⚪ Tối ưu video chuẩn Facebook Page\n';
    step4 = '⚪ Đăng lên Facebook Page';
  } else if (target_platform === 'both') {
    step3 = '⚪ Tối ưu chuẩn Shorts 9:16 & Reels\n';
    step4 = '⚪ Đăng lên YouTube Studio & Facebook Page';
  } else if (shorts_mode === 'short') {
    step3 = '⚪ Tối ưu định dạng 9:16 & thẻ #Shorts\n';
  }

  const statusText = '⏳ <b>ĐANG XỬ LÝ [' + label + ']</b>\n' +
                     '🔗 ' + url + '\n\n' +
                     'Tiến độ: ' + bar + ' <b>10%</b>\n\n' +
                     '🟡 Tiếp nhận & xếp hàng xử lý...\n' +
                     '⚪ Tải video TikTok về VPS\n' +
                     step3 + step4;

  return [{
    json: {
      action: 'submit',
      query_id: cb.id,
      chat_id: String(cb.message.chat.id),
      message_id: cb.message.message_id,
      alert_text: 'Đang chuyển video tới Publisher: ' + label,
      status_text: statusText,
      request_key: reqKey,
      telegram_chat_id: String(cb.message.chat.id),
      telegram_message_id: String(cb.message.message_id),
      source_url: url,
      title: '',
      description: '',
      privacy: privacy,
      shorts_mode: shorts_mode,
      target_platform: target_platform,
      label: label,
      made_for_kids: false,
      rights_confirmed: true
    }
  }];
}

// 2. New message (TikTok link or /publish command)
if (update.message) {
  const msg = update.message;
  if (String(msg.chat?.id) !== allowedChatId || String(msg.from?.id) !== allowedUserId) return [];
  const text = String(msg.text || '').trim();

  const input = text.replace(/^\/(?:publish|public)(?:@[A-Za-z0-9_]+)?\s+/i, '').trim();
  const match = input.match(/https?:\/\/(?:www\.|m\.|vm\.|vt\.)?tiktok\.com\/[^\s\n]+/i);
  if (!match) return [];
  const url = match[0].replace(/[,.!?]+$/, '');

  return [{
    json: {
      action: 'prompt',
      chat_id: String(msg.chat.id),
      message_id: msg.message_id,
      url: url,
      prompt_text: '📹 <b>Đã nhận link TikTok:</b>\n🔗 ' + url + '\n\n👉 <b>Chọn nền tảng & định dạng xuất bản:</b>'
    }
  }];
}

return [];

const p = $('Route & Prepare').first().json;
return [{
  json: {
    request_key: p.request_key,
    telegram_chat_id: p.telegram_chat_id,
    telegram_message_id: String(p.telegram_message_id || ''),
    source_url: p.source_url,
    title: p.title || '',
    description: p.description || '',
    privacy: p.privacy || 'public',
    shorts_mode: p.shorts_mode || 'short',
    target_platform: p.target_platform || 'youtube',
    made_for_kids: false,
    rights_confirmed: true
  }
}];

