(() => {
  const prep = $('Route & Prepare').first().json;
  const q = $json.quota;
  let qText = '';
  if (q) {
    if (q.is_unlimited) {
      qText = '💎 <b>Gói:</b> ' + (q.tier || '').toUpperCase() + ' (Không giới hạn)\n\n';
    } else {
      qText = '📊 <b>Hạn ngạch:</b> Đã dùng ' + q.posts_used + '/' + q.posts_limit + ' bài (Còn ' + q.remaining + ' bài miễn phí tháng ' + q.cycle + ')\n\n';
    }
  }
  let step3 = '⚪ Tối ưu định dạng & thẻ video\n';
  let step4 = '⚪ Đăng lên YouTube Studio';
  if (prep.target_platform === 'facebook') {
    step3 = '⚪ Tối ưu video chuẩn Facebook Page\n';
    step4 = '⚪ Đăng lên Facebook Page';
  } else if (prep.target_platform === 'both') {
    step3 = '⚪ Tối ưu chuẩn Shorts 9:16 & Reels\n';
    step4 = '⚪ Đăng lên YouTube Studio & Facebook Page';
  } else if (prep.shorts_mode === 'short') {
    step3 = '⚪ Tối ưu định dạng 9:16 & thẻ #Shorts\n';
  }

  return '⏳ <b>ĐANG XỬ LÝ [' + prep.label + ']</b>\n' +
         '🔗 ' + prep.source_url + '\n\n' +
         qText +
         'Tiến độ: 🟩⬜⬜⬜⬜⬜⬜⬜⬜⬜ <b>10%</b>\n\n' +
         '🟡 Tiếp nhận & xếp hàng xử lý...\n' +
         '⚪ Tải video TikTok về VPS\n' +
         step3 + step4 + '\n\n' + '👉 <b>Theo dõi tại:</b> <a href="https://publisher.toomi.vn/">Trung tâm tác vụ</a>';
})()
}}

