(() => {
  const prep = $('Route & Prepare').first().json;
  const errObj = $json.response?.body || $json.error || $json;
  let detail = '';
  if (typeof errObj === 'object') {
    detail = errObj.detail || errObj.message || JSON.stringify(errObj);
  } else {
    detail = String(errObj);
  }
  if (detail.includes('hết') && detail.includes('lượt đăng miễn phí')) {
    return '🚫 <b>HẾT HẠN NGẠCH THÁNG NÀY [' + prep.label + ']</b>\n' +
           '🔗 ' + prep.source_url + '\n\n' +
           '⚠️ ' + detail + '\n\n' +
           '💎 <b>Nâng cấp gói Pro để xuất bản không giới hạn:</b> <a href="https://publisher.toomi.vn/">publisher.toomi.vn</a>';
  }
  return '❌ <b>KHÔNG THỂ TIẾP NHẬN YÊU CẦU [' + prep.label + ']</b>\n' +
         '🔗 ' + prep.source_url + '\n\n' +
         '⚠️ <b>Lỗi API:</b> ' + detail;
})()
}}
